package swagger

import (
	"regexp"

	"github.com/nexsoft-git/nexcommon/controller"
	"github.com/nexsoft-git/nexcommon/dto/out"
	"github.com/nexsoft-git/nexcommon/util/validator/basic_validator"
)

var SwaggerContainer SwaggerAutoGenerateDocument
var basic basic_validator.BasicValidator
var securityHeader *regexp.Regexp
var KnownAuth = []string{
	controller.FIXED_TOKEN_VALIDATOR,
	controller.INTERNAL_TOKEN_VALIDATOR,
	controller.EXTERNAL_TOKEN_VALIDATOR,
	controller.USER_TOKEN_VALIDATOR,
}

func init() {
	SwaggerContainer = SwaggerAutoGenerateDocument{
		SwaggerPath: make(SwaggerPath),
		OpenAPI:     "3.0.1",
		SwaggerComponents: SwaggerComponents{
			SwaggerResponses: make(map[string]RequestBodyContentWithDescription),
		},
	}

	basic = basic_validator.BasicValidator{}
	errorResponse := out.DefaultResponse{
		Payload: out.DefaultError{},
	}

	SwaggerContainer.SwaggerComponents.SwaggerResponses["Error"] = ReadResponse(false, "default error response", &errorResponse)
	SwaggerContainer.SwaggerComponents.SwaggerResponses["CountData"] = ReadResponse(false, "default count data response", &out.InitiateGetListDataDTOOut{})

	pattern := "^[a-zA-Z_0-9]+"

	securityHeaders, err := regexp.Compile(pattern)
	if err != nil {
		return
	}

	securityHeader = securityHeaders
	SwaggerContainer.SwaggerComponents.SwaggerSecurity = map[string]SwaggerSecurity{}

}

type SwaggerPath map[string]SwaggerControllerMethods
type SwaggerControllerMethods map[string]SwaggerControllerService

type SwaggerStructDefinitions struct {
	Description string                            `yaml:"description"`
	Properties  map[string]map[string]interface{} `yaml:"properties"`
}

type SwaggerInfo struct {
	Description string `yaml:"description"`
	Title       string `yaml:"title"`
	Version     string `yaml:"version"`
}

type SwaggerParametersWithoutReferences struct {
	In          string        `yaml:"in"`
	Description string        `yaml:"description"`
	Name        string        `yaml:"name"`
	Required    bool          `yaml:"required"`
	Schema      SwaggerSchema `yaml:"schema"`
}

type SwaggerControllerService struct {
	Description string              `yaml:"description"`
	RequestBody interface{}         `yaml:"requestBody,omitempty"`
	Security    []serviceSecurity   `yaml:"security,omitempty"`
	Parameters  []interface{}       `yaml:"parameters"`
	Responses   map[int]interface{} `yaml:"responses"`
	Tags        []string            `yaml:"tags"`
}

func GenerateServiceSecurity(
	name string,
) serviceSecurity {
	temp := make(serviceSecurity)
	temp[RenameSwaggerSecurityName(name)] = []interface{}{}
	return temp
}

type serviceSecurity map[string][]interface{}

type RequestBodyContent struct {
	Content map[string]SwaggerContent `yaml:"content"`
}

type RequestBodyContentWithDescription struct {
	Description string                    `yaml:"description"`
	Content     map[string]SwaggerContent `yaml:"content"`
}

type SwaggerContent struct {
	Schema SwaggerSchemaWithoutType `yaml:"schema"`
}

type SwaggerSchemaWithoutType struct {
	Type       string                 `yaml:"type,omitempty"`
	Format     string                 `yaml:"format,omitempty"`
	Properties map[string]interface{} `yaml:"properties"`
}

type SwaggerReferences struct {
	Ref string `yaml:"$ref"`
}

type SwaggerComponents struct {
	SwaggerResponses map[string]RequestBodyContentWithDescription `yaml:"responses"`
	SwaggerSecurity  map[string]SwaggerSecurity                   `yaml:"securitySchemes"`
}

type SwaggerSecurity struct {
	Type string `json:"type"`
	In   string `json:"in"`
	Name string `json:"name"`
}

type SwaggerSchema struct {
	Type       string                 `yaml:"type"`
	Example    string                 `yaml:"example"`
	Enum       interface{}            `yaml:"enum,omitempty"`
	Properties map[string]interface{} `yaml:"properties"`
}

type SwaggerWithoutReferences struct {
	Type        string `yaml:"type"`
	Description string `yaml:"description"`
}

type SwaggerAutoGenerateDocument struct {
	OpenAPI           string            `yaml:"openapi"`
	Info              SwaggerInfo       `yaml:"info"`
	SwaggerPath       SwaggerPath       `yaml:"paths"`
	SwaggerComponents SwaggerComponents `yaml:"components"`
}
